SELECT *
FROM (
	SELECT class_page.*, ROWNUM AS RN
	FROM (
		SELECT

		FROM CLASS c

		ORDER BY c.WRITE_DATE DESC, c.CLASS_CODE DESC
	) class_page
	WHERE ROWNUM <= #{endRow}
)
WHERE RN >= #{startRow}

SELECT

FROM CLASS c
WHERE c.OPERATOR_CODE = #{authorCode}
  AND c.CLASS_CODE = #{classCode}
  AND c.APPROVAL_STATUS = '승인'
  AND c.STATUS IN ('모집중', '준비중', '폐강')

mapper.update:
UPDATE CLASS
SET STATUS = '준비중'
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND APPROVAL_STATUS = '승인'
  AND STATUS = '모집중'
